import{_ as e,o as n,c as o,a5 as c}from"./chunks/framework.BfQ7H7Qx.js";const u=JSON.parse('{"title":"06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng & Đề xuất Đối tác (AI Features)","description":"","frontmatter":{},"headers":[],"relativePath":"ba/06-ai-features.md","filePath":"ba/06-ai-features.md"}'),d={name:"ba/06-ai-features.md"};function i(h,t,r,a,g,l){return n(),o("div",null,[...t[0]||(t[0]=[c('<h1 id="_06-—-he-sinh-thai-tinh-nang-ai-đo-thi-tri-thuc-xu-huong-đe-xuat-đoi-tac-ai-features" tabindex="-1">06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng &amp; Đề xuất Đối tác (AI Features) <a class="header-anchor" href="#_06-—-he-sinh-thai-tinh-nang-ai-đo-thi-tri-thuc-xu-huong-đe-xuat-đoi-tac-ai-features" aria-label="Permalink to &quot;06 — Hệ sinh thái Tính năng AI, Đồ thị Tri thức Xu hướng &amp; Đề xuất Đối tác (AI Features)&quot;">​</a></h1><p>&gt; Navigation: <a href="./README.html">← BA Overview &amp; Hub</a> · <a href="./05-content-task-workflow.html">← 05 - Content &amp; Workflow</a> · <a href="./07-publishing-social.html">Tiếp: 07 - Publishing &amp; Social →</a> &gt; &gt; <strong>Phạm vi FR chuẩn</strong>: <strong>Mục <code>3.7 AI Features</code> — 19 FR (<code>3.7.1</code> – <code>3.7.19</code>)</strong> | <code>UC-088</code> – <code>UC-106</code> · Use Cases chi tiết: <a href="./use-cases/05-ai-features.html">use-cases/05-ai-features.md</a> · Đặc tả SRS: <a href="./../feature/srs/06-ai-features/README.html">06-ai-features</a>. &gt; Đã loại bỏ hoàn toàn tính năng sinh kịch bản Livestream theo <code>AGENTS.md</code> và đồng bộ 100% với kiến trúc <strong>Brand Hybrid GraphRAG</strong>, <strong>Neo4j Trend Knowledge Graph</strong>, <strong>ComfyUI + Qwen Image 2.1</strong>, <strong>Wan 2.2 Fun VACE 14B + Wan 2.2 S2V 14B</strong>, <strong>Collaborator Directory &amp; AI Recommendation</strong>, cùng cơ chế <strong>4 Nhóm Tác vụ AI Tính phí vs. Tác vụ Miễn phí</strong>.</p><hr><h2 id="_1-bang-tong-hop-19-yeu-cau-chuc-nang-chuan-3-7-1-–-3-7-19" tabindex="-1">1. Bảng Tổng hợp 19 Yêu cầu Chức năng Chuẩn (<code>3.7.1</code> – <code>3.7.19</code>) <a class="header-anchor" href="#_1-bang-tong-hop-19-yeu-cau-chuc-nang-chuan-3-7-1-–-3-7-19" aria-label="Permalink to &quot;1. Bảng Tổng hợp 19 Yêu cầu Chức năng Chuẩn (`3.7.1` – `3.7.19`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã FR</th><th style="text-align:center;">Mã UC</th><th style="text-align:left;">Tên Chức năng Chuẩn (Atomic CRUD FR)</th><th style="text-align:left;">Actors / Roles Chuẩn</th><th style="text-align:center;">Phân loại Credit</th><th style="text-align:left;">Mô tả Nghiệp vụ Cốt lõi</th></tr></thead><tbody><tr><td style="text-align:center;"><strong><code>3.7.1</code></strong></td><td style="text-align:center;"><code>UC-088</code></td><td style="text-align:left;"><strong>View Trending Topics Suggestions</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem bảng điều khiển chủ đề &amp; từ khóa xu hướng thịnh hành tại Việt Nam (tính điểm bùng nổ BM25 kết hợp xếp hạng đồ thị Neo4j Personalized PageRank &amp; Betweenness Centrality, <code>BR-45</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.2</code></strong></td><td style="text-align:center;"><code>UC-089</code></td><td style="text-align:left;"><strong>View AI Trend Knowledge Graph</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Admin</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Khám phá trực quan Đồ thị Tri thức Xu hướng (<code>Neo4j Knowledge Graph</code>) thể hiện mối liên hệ giữa Chủ đề (<code>Topic</code>), Từ khóa (<code>Keyword</code>), Hashtag và Thực thể (<code>BR-45</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.3</code></strong></td><td style="text-align:center;"><code>UC-090</code></td><td style="text-align:left;"><strong>View Brand Knowledge Documents</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code>, <code>Client</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem danh sách và tìm kiếm ngữ nghĩa các tài liệu Brand Guideline trong kho RAG của Workspace cùng trạng thái vector hóa (<code>PENDING</code>, <code>INDEXED</code>, <code>FAILED</code>, <code>BR-20</code>, <code>BR-46</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.4</code></strong></td><td style="text-align:center;"><code>UC-091</code></td><td style="text-align:left;"><strong>Upload Brand Knowledge Document</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Tải lên tài liệu Brand Guideline (<code>PDF</code>, <code>DOCX</code>, <code>TXT</code>, <code>HTML</code> ≤ 10 MB hoặc Web URL) để lưu S3, băm nhỏ văn bản và tạo vector nhúng trong phân vùng ChromaDB riêng của Workspace (<code>BR-20</code>, <code>BR-46</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.5</code></strong></td><td style="text-align:center;"><code>UC-092</code></td><td style="text-align:left;"><strong>Delete Brand Knowledge Document</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Client</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xóa tài liệu Brand Guideline trên S3 đồng thời xóa sạch các đoạn vector nhúng tương ứng trong ChromaDB (<code>BR-20</code>, <code>BR-47</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.6</code></strong></td><td style="text-align:center;"><code>UC-093</code></td><td style="text-align:left;"><strong>Generate Caption</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>CONTENT_GENERATE</code>)</td><td style="text-align:left;">Sinh nội dung bài viết / caption đa nền tảng kết hợp ngữ cảnh thương hiệu (RAG) và xu hướng Neo4j; hỗ trợ tinh chỉnh biến thể (<code>CAPTION_VARIANTS</code> — miễn phí) và làm mượt văn phong tự nhiên (<code>Content Humanizer</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.7</code></strong></td><td style="text-align:center;"><code>UC-094</code></td><td style="text-align:left;"><strong>Generate Ambassador</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>AMBASSADOR_GENERATE</code>)</td><td style="text-align:left;">Khởi tạo hình mẫu Đại sứ Thương hiệu ảo bằng AI (<code>Virtual Brand Ambassador</code> — ngoại hình, phong cách, trang phục, bối cảnh) và sinh bảng góc mặt nhân vật (<code>CHARACTER_SHEET</code> — miễn phí).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.8</code></strong></td><td style="text-align:center;"><code>UC-095</code></td><td style="text-align:left;"><strong>View Image Style Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Duyệt thư viện mẫu phong cách hình ảnh thương mại (<code>Commercial Image Presets</code> — Studio, Lifestyle, Minimalist, Luxury, Cyber, Seasonal...).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.9</code></strong></td><td style="text-align:center;"><code>UC-096</code></td><td style="text-align:left;"><strong>Generate Image</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>COMMERCIAL_IMAGE</code>)</td><td style="text-align:left;">Sinh ảnh quảng cáo thương mại / ảnh sản phẩm chất lượng cao bằng AI theo prompt, mẫu phong cách (<code>3.7.8</code>) hoặc ghép cùng Đại sứ thương hiệu (<code>3.7.7</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.10</code></strong></td><td style="text-align:center;"><code>UC-097</code></td><td style="text-align:left;"><strong>View Video Style Template</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Duyệt thư viện mẫu phong cách, bố cục chuyển cảnh và tỷ lệ khung hình (<code>9:16</code>, <code>16:9</code>, <code>1:1</code>) cho video ngắn / video sản phẩm.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.11</code></strong></td><td style="text-align:center;"><code>UC-098</code></td><td style="text-align:left;"><strong>Generate Video</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;"><strong>Tính phí</strong> (<code>VIDEO_GENERATE</code>)</td><td style="text-align:left;">Sinh video ngắn / video quảng cáo sản phẩm bằng AI (<code>AI Video Studio</code> / <code>Product Video</code> / <code>Video Space</code>) theo kịch bản, hình ảnh đầu vào và mẫu phong cách (<code>3.7.10</code>), xử lý bất đồng bộ kèm hoàn trả credit nếu lỗi.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.12</code></strong></td><td style="text-align:center;"><code>UC-099</code></td><td style="text-align:left;"><strong>Export File</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xuất nội dung AI đã tạo hoặc lưu trực tiếp hình ảnh/video/văn bản về thiết bị hoặc đẩy thẳng vào <code>Material Library</code> / phần <code>TaskSection</code> của công việc đang mở.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.13</code></strong></td><td style="text-align:center;"><code>UC-100</code></td><td style="text-align:left;"><strong>Crawl Schedule Config</strong></td><td style="text-align:left;"><code>Admin</code></td><td style="text-align:center;">Hệ thống</td><td style="text-align:left;">Cấu hình lịch trình thu thập dữ liệu xu hướng tự động (<code>Crawler Cron Schedule</code>), nguồn thu thập đa nền tảng và kích hoạt chạy đường ống xu hướng tức thì (<code>Run Pipeline Now</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.14</code></strong></td><td style="text-align:center;"><code>UC-101</code></td><td style="text-align:left;"><strong>Suggest Hashtag Trend</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code>, <code>Creator</code></td><td style="text-align:center;">Miễn phí (<code>HASHTAG_GENERATE</code>)</td><td style="text-align:left;">Gợi ý bộ Hashtag theo ngữ cảnh nội dung bài viết kết hợp dữ liệu xu hướng thực tế trong Workspace.</td></tr><tr><td style="text-align:center;"><strong><code>3.7.15</code></strong></td><td style="text-align:center;"><code>UC-102</code></td><td style="text-align:left;"><strong>View Collaborator Directory</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xem và lọc danh bạ đối tác truyền thông bên thứ ba của Agency (KOL/KOC, Báo điện tử, Trang treo Banner, Kênh truyền hình TV, <code>BR-20</code>, <code>BR-51</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.16</code></strong></td><td style="text-align:center;"><code>UC-103</code></td><td style="text-align:left;"><strong>Create Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Thêm mới hồ sơ đối tác truyền thông bên thứ ba vào danh bạ của Agency (Tên, Phân loại kênh, Lĩnh vực, Quy mô độc giả/follower, Đơn giá dự kiến, Liên hệ, <code>BR-15</code>, <code>BR-51</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.17</code></strong></td><td style="text-align:center;"><code>UC-104</code></td><td style="text-align:left;"><strong>Update Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Cập nhật thông tin hồ sơ đối tác và tiến độ hợp tác trong chiến dịch (<code>CONTACTED -&gt; NEGOTIATING -&gt; CONFIRMED -&gt; LIVE_ON_AIR -&gt; COMPLETED</code>, <code>BR-51</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.18</code></strong></td><td style="text-align:center;"><code>UC-105</code></td><td style="text-align:left;"><strong>Remove Collaborator Profile</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Xóa mềm hoặc ngừng kích hoạt hồ sơ đối tác truyền thông khỏi danh bạ hoạt động của Agency mà vẫn bảo toàn lịch sử chi phí/nghiệm thu cũ (<code>BR-15</code>, <code>BR-51</code>).</td></tr><tr><td style="text-align:center;"><strong><code>3.7.19</code></strong></td><td style="text-align:center;"><code>UC-106</code></td><td style="text-align:left;"><strong>Recommend Collaborator</strong></td><td style="text-align:left;"><code>Owner</code>, <code>Manager</code></td><td style="text-align:center;">Miễn phí</td><td style="text-align:left;">Hệ thống AI phân tích mục tiêu chiến dịch, ngành hàng và ngân sách để đề xuất thông minh danh sách đối tác truyền thông bên thứ ba phù hợp kèm điểm tương thích (<code>BR-51</code>, <code>BR-52</code>).</td></tr></tbody></table><hr><h2 id="_2-đac-ta-nghiep-vu-chi-tiet-tung-nhom-tinh-nang-ai" tabindex="-1">2. Đặc tả Nghiệp vụ Chi tiết Từng Nhóm Tính năng AI <a class="header-anchor" href="#_2-đac-ta-nghiep-vu-chi-tiet-tung-nhom-tinh-nang-ai" aria-label="Permalink to &quot;2. Đặc tả Nghiệp vụ Chi tiết Từng Nhóm Tính năng AI&quot;">​</a></h2><h3 id="_2-1-kham-pha-xu-huong-đo-thi-tri-thuc-3-7-1-3-7-2-3-7-13-3-7-14" tabindex="-1">2.1. Khám phá Xu hướng &amp; Đồ thị Tri thức (<code>3.7.1</code>, <code>3.7.2</code>, <code>3.7.13</code>, <code>3.7.14</code>) <a class="header-anchor" href="#_2-1-kham-pha-xu-huong-đo-thi-tri-thuc-3-7-1-3-7-2-3-7-13-3-7-14" aria-label="Permalink to &quot;2.1. Khám phá Xu hướng &amp; Đồ thị Tri thức (`3.7.1`, `3.7.2`, `3.7.13`, `3.7.14`)&quot;">​</a></h3><ul><li><strong>Đường ống thu thập đa nền tảng (<code>3.7.13 Crawl Schedule Config</code>)</strong>: <ul><li>Do <code>Admin</code> quản lý tại <code>/admin/crawler</code>. Hệ thống thu thập xu hướng theo lịch định kỳ hoặc kích hoạt chạy ngay (<code>Run Pipeline Now</code>), trích xuất chủ đề, từ khóa, cảm xúc (<code>sentiment</code>) và lưu trữ vào <strong>Neo4j Knowledge Graph</strong> cùng MongoDB.</li></ul></li><li><strong>Trình khám phá xu hướng trong Workspace (<code>3.7.1</code> &amp; <code>3.7.2</code>)</strong>: <ul><li>Tại <code>/workspaces/:id/trends</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code> (kể cả trong chế độ <code>PERSONAL</code>) xem được các xu hướng mới nhất, bấm vào từng nút trên <strong>Đồ thị Tri thức (<code>AI Trend Knowledge Graph</code>)</strong> để xem các góc tiếp cận nội dung (<code>content angles</code>) và chuyển hóa ngay 1 chạm thành bài đăng hoặc kịch bản video.</li></ul></li><li><strong>Gợi ý Hashtag thông minh (<code>3.7.14 Suggest Hashtag Trend</code>)</strong>: <ul><li>Ngay trong trình soạn thảo <code>POST.CAPTION</code> / <code>VIDEO.CAPTION</code>, người dùng bấm gợi ý Hashtag theo nội dung đang viết. Tác vụ này thuộc nhóm <code>HASHTAG_GENERATE</code> (<strong>hoàn toàn miễn phí credit</strong>, <code>unit_credits = 0</code>).</li></ul></li></ul><h3 id="_2-2-kho-tri-thuc-thuong-hieu-rag-3-7-3-–-3-7-5" tabindex="-1">2.2. Kho Tri thức Thương hiệu RAG (<code>3.7.3</code> – <code>3.7.5</code>) <a class="header-anchor" href="#_2-2-kho-tri-thuc-thuong-hieu-rag-3-7-3-–-3-7-5" aria-label="Permalink to &quot;2.2. Kho Tri thức Thương hiệu RAG (`3.7.3` – `3.7.5`)&quot;">​</a></h3><ul><li>Cho phép mỗi Workspace (cả <code>AGENCY</code> lẫn <code>PERSONAL</code>) xây dựng bộ nhớ dài hạn cho AI: <ul><li>Khi người dùng tải lên tài liệu hướng dẫn thương hiệu, thông số sản phẩm hoặc đề cương bài tập lớn (<code>3.7.4 Upload Brand Knowledge Document</code>), <code>brandhub-ai-service</code> trích xuất văn bản, chia nhỏ (<code>chunking</code>) và lập chỉ mục vector.</li><li>Khi gọi <code>3.7.6 Generate Caption</code>, hệ thống tự động truy xuất các đoạn tri thức liên quan nhất (<code>RAG retrieval</code>) kết hợp với ngữ cảnh xu hướng Neo4j để sinh bài viết bám sát thông tin thật, không bịa đặt thông số sản phẩm.</li></ul></li></ul><h3 id="_2-3-studio-sang-tao-noi-dung-đa-phuong-thuc-3-7-6-–-3-7-12" tabindex="-1">2.3. Studio Sáng tạo Nội dung Đa phương thức (<code>3.7.6</code> – <code>3.7.12</code>) <a class="header-anchor" href="#_2-3-studio-sang-tao-noi-dung-đa-phuong-thuc-3-7-6-–-3-7-12" aria-label="Permalink to &quot;2.3. Studio Sáng tạo Nội dung Đa phương thức (`3.7.6` – `3.7.12`)&quot;">​</a></h3><ol><li><strong>Sinh Bài viết &amp; Tinh chỉnh Văn phong (<code>3.7.6 Generate Caption</code>)</strong>: <ul><li>Người dùng chọn nền tảng mục tiêu (<strong>Facebook, Instagram, TikTok, Threads</strong>), giọng văn (<code>Tone of Voice</code>), độ dài và từ khóa.</li><li>Tác vụ sinh bài mới tính phí theo mã <code>CONTENT_GENERATE</code>. Các bước tạo biến thể / rút gọn / mở rộng / làm tự nhiên văn phong (<code>CAPTION_VARIANTS</code> / <code>Content Humanizer</code>) được miễn phí credit.</li><li>Nội dung sinh ra tự động đi qua bộ lọc an toàn (<code>Caption Text Moderation</code> / <code>3.6.33</code>) trước khi hiển thị.</li></ul></li><li><strong>Đại sứ Thương hiệu Ảo &amp; Ảnh Thương mại (<code>3.7.7</code>, <code>3.7.8</code>, <code>3.7.9</code>)</strong>: <ul><li>Tạo nhân vật đại sứ thương hiệu nhất quán (<code>AMBASSADOR_GENERATE</code> — tính phí; sinh bảng góc mặt <code>CHARACTER_SHEET</code> — miễn phí).</li><li>Chọn mẫu phong cách ảnh thương mại (<code>3.7.8 View Image Style Template</code>) và sinh ảnh sản phẩm/quảng cáo (<code>3.7.9 Generate Image</code> — mã giá <code>COMMERCIAL_IMAGE</code>).</li></ul></li><li><strong>Studio Video AI (<code>3.7.10</code>, <code>3.7.11</code>, <code>3.7.12</code>)</strong>: <ul><li>Hỗ trợ xem mẫu phong cách video (<code>3.7.10</code>) và tạo video bằng AI (<code>3.7.11 Generate Video</code> — mã giá <code>VIDEO_GENERATE</code>) trong các không gian chuyên biệt: <strong>AI Video Studio</strong>, <strong>Product Video Studio</strong> và <strong>Video Space</strong>.</li><li>Vì quá trình dựng video AI chạy bất đồng bộ (asynchronous job), hệ thống thực hiện <strong>tạm giữ credit (<code>HOLD</code> / <code>Reserve</code>)</strong> khi bắt đầu job; chỉ khi video hoàn tất thành công mới thực hiện <strong>khấu trừ thật (<code>SETTLE</code> / <code>Commit</code>)</strong>; nếu provider lỗi hoặc timeout, hệ thống tự động <strong>hoàn trả toàn bộ số credit tạm giữ (<code>RELEASE</code>)</strong>.</li></ul></li></ol><h3 id="_2-4-danh-ba-cong-tac-vien-kol-đe-xuat-bang-ai-3-7-15-–-3-7-19" tabindex="-1">2.4. Danh bạ Cộng tác viên / KOL &amp; Đề xuất bằng AI (<code>3.7.15</code> – <code>3.7.19</code>) <a class="header-anchor" href="#_2-4-danh-ba-cong-tac-vien-kol-đe-xuat-bang-ai-3-7-15-–-3-7-19" aria-label="Permalink to &quot;2.4. Danh bạ Cộng tác viên / KOL &amp; Đề xuất bằng AI (`3.7.15` – `3.7.19`)&quot;">​</a></h3><ul><li>Phục vụ trực tiếp cho việc lập kế hoạch truyền thông và thực thi loại công việc <strong><code>KOL_BOOKING</code></strong>: <ul><li><code>Owner</code> và <code>Manager</code> quản lý danh bạ đối tác/KOL (<code>3.7.15</code>–<code>3.7.18</code>).</li><li>Khi cần chọn KOL cho chiến dịch hoặc công việc <code>KOL_BOOKING</code>, <code>Owner</code>, <code>Manager</code>, <code>Creator</code> gọi <strong><code>3.7.19 Recommend Collaborator</code></strong>: AI đối chiếu thông tin chiến dịch với hồ sơ trong danh bạ để xếp hạng các KOL phù hợp nhất và điền nhanh vào phần <code>KOL.SHORTLIST</code>.</li></ul></li></ul><hr><h2 id="_3-co-che-tru-ai-credit-trong-che-đo-agency-va-personal" tabindex="-1">3. Cơ chế Trừ AI Credit trong Chế độ <code>AGENCY</code> và <code>PERSONAL</code> <a class="header-anchor" href="#_3-co-che-tru-ai-credit-trong-che-đo-agency-va-personal" aria-label="Permalink to &quot;3. Cơ chế Trừ AI Credit trong Chế độ `AGENCY` và `PERSONAL`&quot;">​</a></h2><p>Theo kiến trúc hợp nhất tại <a href="./08-subscription-billing.html">08 - Subscription &amp; Billing</a> và đặc tả <a href="./../feature/srs/08-subscription-billing/README.html">3.9 Subscription &amp; Billing</a>:</p><ol><li><strong>Nguồn tiền duy nhất (<code>Single Funding Source</code>)</strong>: Mọi chi phí AI đều được trừ từ ví <code>agency_credit_wallets</code> của <code>Agency</code> (hoặc của <code>Personal Hub Agency</code> khi ở chế độ <code>PERSONAL</code>), ưu tiên trừ <strong>Plan Credit (credit theo chu kỳ gói)</strong> trước rồi mới trừ <strong>Purchased Credit (credit mua thêm không hết hạn)</strong>.</li><li><strong>Trần ngân sách cấp Workspace (<code>Workspace Credit Cap</code>)</strong>: <ul><li><code>Owner</code> có thể đặt hạn mức <code>workspaceLimit</code> cho từng Workspace (hoặc để <code>NULL</code> = dùng tự do theo số dư ví tổng; <code>0</code> = khóa các tác vụ AI tính phí).</li><li>Cả <code>Owner</code>, <code>Manager</code> và <code>Creator</code> khi dùng AI trong một Workspace đều tiêu thụ ngân sách của Workspace đó.</li></ul></li><li><strong>4 Nhóm Tác vụ Tính phí Duy nhất</strong>: <ul><li>Chỉ đúng 4 nhóm <code>CONTENT_GENERATE</code>, <code>AMBASSADOR_GENERATE</code>, <code>COMMERCIAL_IMAGE</code>, <code>VIDEO_GENERATE</code> mới trừ credit theo bảng giá cố định của <code>Admin</code>. Mọi thao tác AI hỗ trợ khác đều miễn phí (<code>unit_credits = 0</code>).</li></ul></li></ol><hr><h2 id="_4-bang-tham-chieu-quy-tac-nghiep-vu-br-45-–-br-52" tabindex="-1">4. Bảng Tham chiếu Quy tắc Nghiệp vụ (<code>BR-45</code> – <code>BR-52</code>) <a class="header-anchor" href="#_4-bang-tham-chieu-quy-tac-nghiep-vu-br-45-–-br-52" aria-label="Permalink to &quot;4. Bảng Tham chiếu Quy tắc Nghiệp vụ (`BR-45` – `BR-52`)&quot;">​</a></h2><table tabindex="0"><thead><tr><th style="text-align:center;">Mã BR</th><th style="text-align:left;">Tên Quy tắc</th><th style="text-align:left;">Quy định Ràng buộc Cụ thể</th><th style="text-align:left;">FR Áp dụng</th></tr></thead><tbody><tr><td style="text-align:center;"><code>BR-45</code></td><td style="text-align:left;"><strong>Làm mới Xu hướng Định kỳ &amp; Dự phòng Cache</strong></td><td style="text-align:left;">Đường ống xu hướng kết hợp lọc spam (<code>T1</code>), nhãn PhoBERT (<code>T2</code>), điểm đột biến 4 tín hiệu (<code>T4_BurstStep</code>) và độ lan truyền đồ thị Neo4j (<code>T6</code>), lưu đệm Redis ZSET (<code>TTL 6h</code>). Nếu nguồn cào gián đoạn, giao diện hiển thị bản chụp xu hướng hợp lệ gần nhất thay vì báo lỗi trắng trang.</td><td style="text-align:left;"><code>3.7.1</code>, <code>3.7.2</code>, <code>3.7.13</code>, <code>3.7.14</code></td></tr><tr><td style="text-align:center;"><code>BR-46</code></td><td style="text-align:left;"><strong>Kiểm định Magic-Byte &amp; Cô lập Kho Brand RAG</strong></td><td style="text-align:left;">Tệp tải lên kho tri thức (<code>PDF</code>, <code>DOCX</code>, <code>TXT</code>, <code>HTML</code> ≤ <code>10 MB</code>) được xác thực chữ ký byte thực tế, cắt khúc <code>500</code> ký tự (<code>overlap 50</code>) và lập chỉ mục vector <code>384</code> chiều vào phân vùng ChromaDB cô lập riêng theo thương hiệu/Workspace.</td><td style="text-align:left;"><code>3.7.3</code>, <code>3.7.4</code></td></tr><tr><td style="text-align:center;"><code>BR-47</code></td><td style="text-align:left;"><strong>Xóa Đồng bộ Ba Tầng cho Tài liệu RAG</strong></td><td style="text-align:left;">Khi xóa tài liệu Brand Knowledge (<code>3.7.5</code>), hệ thống dọn sạch đồng bộ tệp gốc trên S3, bản ghi <code>knowledge_documents</code> trong MongoDB và toàn bộ các vector chunks tương ứng trong ChromaDB/Neo4j.</td><td style="text-align:left;"><code>3.7.5</code></td></tr><tr><td style="text-align:center;"><code>BR-48</code></td><td style="text-align:left;"><strong>Giữ chỗ Trước, Khấu trừ Sau (<code>Hold-Settle-Release</code>)</strong></td><td style="text-align:left;">Trước khi gọi <code>brandhub-ai-service</code>, <code>brandhub-business-service</code> kiểm tra trần <code>workspace_credit_limits</code> và khóa tạm số credit trên <code>ai_credit_reservations</code>; chỉ khấu trừ thật khi nhận kết quả hợp lệ, tự động giải phóng <code>100%</code> nếu lỗi hoặc quá hạn.</td><td style="text-align:left;"><code>3.7.6</code>, <code>3.7.7</code>, <code>3.7.9</code>, <code>3.7.11</code></td></tr><tr><td style="text-align:center;"><code>BR-49</code></td><td style="text-align:left;"><strong>Chống Ảo giác &amp; Kiểm duyệt Đầu ra AI</strong></td><td style="text-align:left;">Caption sinh ra bắt buộc tuân thủ dữ kiện trong <code>RAG Context</code> (ưu tiên Groq Llama 3, tự động chuyển dự phòng sang Anthropic Claude khi quá tải) và đi qua lớp kiểm tra an toàn cộng đồng trước khi trả về trình soạn thảo.</td><td style="text-align:left;"><code>3.7.6</code></td></tr><tr><td style="text-align:center;"><code>BR-50</code></td><td style="text-align:left;"><strong>Khóa Kịch bản Video VACE &amp; Bảo toàn Khuôn mặt Đại sứ</strong></td><td style="text-align:left;">Kịch bản sinh video sản phẩm (<code>ltx_director.py</code>) được kiểm định JSON Schema (<code>15–21s</code>, <code>16 FPS</code>, độ dài đoạn <code>4n+1</code>) trước khi gửi xuống GPU worker <strong>Wan 2.2 Fun VACE 14B + Qwen Image 2.1 + S2V</strong>.</td><td style="text-align:left;"><code>3.7.7</code>–<code>3.7.12</code></td></tr><tr><td style="text-align:center;"><code>BR-51</code></td><td style="text-align:left;"><strong>Phạm vi Danh bạ Đối tác cấp Agency</strong></td><td style="text-align:left;">Hồ sơ <code>third_party_collaborators</code> thuộc sở hữu cấp <code>Agency</code> để tái sử dụng xuyên suốt các <code>MediaCampaign</code> thông qua bảng liên kết <code>campaign_collaborators</code>; xóa đối tác là xóa mềm để bảo toàn lịch sử chiến dịch cũ.</td><td style="text-align:left;"><code>3.7.15</code>–<code>3.7.18</code></td></tr><tr><td style="text-align:center;"><code>BR-52</code></td><td style="text-align:left;"><strong>Xếp hạng Tương thích Đối tác theo Ngữ cảnh Chiến dịch</strong></td><td style="text-align:left;">Gợi ý đối tác AI (<code>3.7.19</code>) chấm điểm dựa trên độ khớp ngành hàng, kênh truyền thông, quy mô tệp độc giả và trần ngân sách của chiến dịch đang mở.</td><td style="text-align:left;"><code>3.7.19</code></td></tr></tbody></table><hr><h2 id="_5-tham-chieu-kien-truc-ky-thuat-lien-quan" tabindex="-1">5. Tham chiếu Kiến trúc Kỹ thuật Liên quan <a class="header-anchor" href="#_5-tham-chieu-kien-truc-ky-thuat-lien-quan" aria-label="Permalink to &quot;5. Tham chiếu Kiến trúc Kỹ thuật Liên quan&quot;">​</a></h2><ul><li>Kiến trúc dịch vụ AI &amp; Hợp đồng REST nội bộ: <a href="./../architecture/ai-service-architecture.html">AI Service Architecture</a> · <a href="./../architecture/business-ai-rest-contract.html">Business ↔ AI REST Contract</a>.</li><li>Thuật toán NLP, Burst, GraphRAG &amp; GPU Worker Wan VACE: <a href="./../ai-models/README.html">AI Models &amp; Research Hub</a>.</li></ul>',25)])])}const m=e(d,[["render",i]]);export{u as __pageData,m as default};
